    "headline": "오늘의 핵심은 책을 ‘읽는 콘텐츠’에서 실제 행동과 공동 기록으로 확장하는 것입니다. 100일 마라톤 신간은 독서 뒤 실천을, 한글날 100주년 캠페인은 개인의 언어를 모으는 참여를, AI 법·심리 전문서 동시 출간은 조직 단위 구독 기회를 보여줍니다.",
