          "고객 경험 · 목표 거리 선택 → 책의 오늘 분량 10분 읽기 → 외부 러닝앱 캡처 또는 수동 거리 인증 → 저자 음성 체크인 해제 → 25·50·75·100일 배지 → 완주자 온라인 토크. 협업 후보는 21세기북스, 러너임바, 러닝크루·러닝앱·스포츠 브랜드입니다.",
